package com.gregtech.gregtech.content.logistics;
import java.util.List;
public final class LongDistanceCatalog {private LongDistanceCatalog(){}public record Spec(String id,String kind,long voltage,float hardness,float resistance){}public static final List<Spec> ALL=List.of(new Spec("long_dist_pipe","LEGACY_PIPE",4096L,3f,3f),new Spec("long_dist_wire","WIRE",4096L,3f,3f),new Spec("long_dist_endpoint_item","ITEM_ENDPOINT",0L,5f,5f),new Spec("long_dist_endpoint_fluid","FLUID_ENDPOINT",0L,5f,5f),new Spec("long_dist_transformer_ulv","TRANSFORMER",2048L,4f,4f),new Spec("long_dist_transformer_lv","TRANSFORMER",8192L,4f,4f),new Spec("long_dist_transformer_mv","TRANSFORMER",32768L,4f,4f),new Spec("long_dist_transformer_zpm","TRANSFORMER",131072L,4f,4f),new Spec("long_dist_transformer_uv","TRANSFORMER",524288L,4f,4f),new Spec("long_dist_pipe_item","ITEM_PIPE",4096L,3.5f,10f),new Spec("long_dist_pipe_fluid","FLUID_PIPE",4096L,3.5f,10f),new Spec("long_dist_wire_ev","WIRE",4096L,3.5f,10f),new Spec("long_dist_wire_iv","WIRE",16384L,3.5f,10f),new Spec("long_dist_wire_luv","WIRE",65536L,3.5f,10f),new Spec("long_dist_wire_zpm","WIRE",262144L,3.5f,10f),new Spec("long_dist_wire_uv","WIRE",1048576L,3.5f,10f));public static long voltage(String id){return ALL.stream().filter(s->s.id().equals(id)).findFirst().orElseThrow().voltage();}}
